int main(int argc,char** argv){try{
 std::cout.setf(std::ios::unitbuf);need(argc==7,"g1_entry_checks package real-chapter real-ordinary real-recovery isolated-root write|load|rules|ordinary|recovery");auto c=loadCombatContent(argv[1]);const auto root=std::filesystem::path(argv[5]);std::filesystem::create_directories(root);const std::string mode=argv[6];
 const auto chapter=decodeSave(c,read(argv[2]));const auto ordinary=decodeSave(c,read(argv[3]));const auto recovery=decodeSave(c,read(argv[4]));
 need(chapter.continuation.kind=="chapter_handoff_after_file"&&ordinary.continuation.kind=="ordinary"&&recovery.continuation.kind=="development_f5_recovery","Three real sources missing");
 for(const auto& s:{chapter,ordinary,recovery}){need(s.contentCompatibility==c.compatibility&&s.session.worldFlags.contains(c.facts.switches.at(564))&&!s.session.worldFlags.at(c.facts.switches.at(564)),"Source fact adapter incorrect");auto old=Json::parse(read(s.continuation.kind=="ordinary"?argv[3]:s.continuation.kind=="development_f5_recovery"?argv[4]:argv[2]));need(s.session.magazines==decodeSave(*c.legacySource,old.dump()).session.magazines,"Migration reset old I15 magazine");old["session"]["magazines"].push_back({13,13});reject([&]{decodeSave(c,old.dump());});old=Json::parse(read(argv[2]));old["session"]["world_flags"].push_back({c.facts.switches.at(564),false});reject([&]{decodeSave(c,old.dump());});}
 if(mode=="load"){
  SaveFiles files(c,root);auto disk=files.read(2);const auto bytes=read((root/"slot-02.json").string().c_str());Driver run(c,root/"load");run.game.configureSaveDirectory(root);finishTitleOpening(run.game);run.game.returnToTitle();finishTitleOpening(run.game);run.tick(key());run.tick(key(InputAction::Down));run.tick(key());need(run.game.mapId()==132&&run.game.world().player().motion.tile()==TilePosition{9,10}&&run.game.world().player().motion.facing()==Direction::Up,"Independent Load wrong location");need(run.game.session().saveCount()==disk.session.saveCount&&run.game.session().variable(399)==disk.continuation.statisticBefore+1&&run.game.session().flag(360)&&run.game.session().flag(564)&&run.game.session().exportState().magazines==disk.session.magazines&&run.game.session().exportState().inventory==disk.session.inventory&&run.game.session().exportState().mainWeapon==disk.session.mainWeapon&&run.game.session().conditions().bleedingTicks==disk.session.conditions.bleedingTicks,"Independent Load lost facts/ammo/conditions/count");run.disabledSave();run.roundtrip();need(read((root/"slot-02.json").string().c_str())==bytes,"Load changed disk");run.game.returnToTitle();finishTitleOpening(run.game);run.tick(key());run.tick(key(InputAction::Down));run.tick(key(InputAction::Down));run.tick(key());need(run.game.mode()==ApplicationMode::Playing&&run.game.session().conditions().bleedingTicks==600,"Independent process public Load lost bleeding600");std::cout<<"Independent process public M132 Load/movement/menu/leave/re-enter, partial I15, facts/statistics and bleeding600 engineering disk passed\n";return 0;
 }
 if(mode=="rules"){SaveFiles files(c,root);rules(c,files.read(2),root);return 0;}
 const auto source=mode=="ordinary"?argv[3]:mode=="recovery"?argv[4]:argv[2];const auto raw=read(source);const auto s=decodeSave(c,raw);std::ofstream(root/"slot-01.json")<<raw;Driver run(c,root);run.game.configureSaveDirectory(root);finishTitleOpening(run.game);run.fromOld(s);need(run.game.session().flag(360)&&!run.game.session().knowsSkill(3),"Natural awake state wrong");run.disabledSave();
 if(mode=="write"){
  // Consume the original rewarded I15 through the public menu and firing input before first ordinary save.
  run.equip(15);run.tick(key(InputAction::Weapon));run.pause();run.tick(key(InputAction::Attack));run.pause();run.tick(key(InputAction::Attack));run.pause();need(run.game.session().magazine(15)==6,"Natural I15 reload/fire did not leave6");InputFrame hold;hold.buttons[int(InputAction::Weapon)].held=true;for(int n=0;n<8;++n){run.tick(hold);}run.tick();run.pause();need(!run.game.raised(),"Natural I15 did not lower");
 }
 const auto pre=run.game.session().exportState();run.hall();need(run.game.session().knowsSkill(3)&&!run.game.session().knowsSkill(4),"Hall did not enable mixing");need(run.game.session().exportState().magazines==pre.magazines,"Mansion entrance refilled weapons");const auto disk=run.save(root);need(disk.session.magazines==pre.magazines&&disk.session.mainWeapon==pre.mainWeapon&&disk.session.conditions.bleedingTicks==0,"Natural first save changed equipment/ammo or invented bleeding");
 for(auto [map,a]:std::map<int,std::string>{{128,"m127-e3-p2-c8"},{129,"m128-e7-p2-c8"},{132,"m129-e4-p2-c8"}}){need(run.sounds.contains({map,c.cue(a).at("sound").at("resource").get<std::string>()}),"Door post-transfer close sound missing");}
 run.roundtrip();need(read(source)==raw&&read((root/"slot-01.json").string().c_str())==raw,"Natural route altered source disk");std::filesystem::create_directories(root/"load");std::cout<<"NATURAL_G1_FIRST_SAVE source="<<s.continuation.kind<<" ticks="<<run.ticks<<" maps="<<Json(run.maps)<<" I15="<<disk.session.magazines.at(15)<<" count="<<disk.session.saveCount<<" diskV399="<<disk.session.variables.at(399)<<" natural bleeding0 (FullHeal), engineering bleeding600 separately\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
